import React, { useState } from "react";
import { Link } from "react-scroll";
import "./Navbar.css"; // Importa el archivo de estilos

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);

  const toggleMenu = () => setIsOpen(!isOpen);

  return (
    <nav className="navbar">
      <div className="navbar-container">
        <h1 className="logo">
          <Link to="home" smooth={true} duration={500}>FREE TRADER'S</Link>
        </h1>

          {/* Menú hamburguesa con icono real de Font Awesome */}
          <div
          className={`menu-icon ${isOpen ? "open" : ""}`}
          onClick={toggleMenu}
        >
          <i className={`fa ${isOpen ? "fa-times" : "fa-bars"}`} aria-hidden="true"></i>
        </div>

        {/* Enlaces de navegación */}
        <ul className={`nav-links ${isOpen ? "active" : ""}`}>
          <li><Link to="home" smooth={true} duration={500} onClick={toggleMenu}>Inicio</Link></li>
          <li><Link to="cursos" smooth={true} duration={500} onClick={toggleMenu}>Cursos</Link></li>
          <li><Link to="sobre-nosotros" smooth={true} duration={500} onClick={toggleMenu}>Sobre Nosotros</Link></li>
          <li><Link to="contacto" smooth={true} duration={500} onClick={toggleMenu}>Contacto</Link></li>
        </ul>
      </div>
    </nav>
  );
};

export default Navbar;
